//! Protobuf messages and gRPC services shared by all crates.
//!
//! Rust port of the upstream Go `protos/pb.proto` plus the `api.proto` it imports
//! from `dgo`. Messages and tonic clients/servers are generated by `protoc`
//! at build time (see `build.rs` and `proto/`); `raftpb` is hand-authored
//! because upstream `raft.proto` is `proto2`, which prost cannot compile.
//! Field numbers and service shapes stay wire-compatible with the Go nodes.

#![warn(missing_docs)]

use prost::Message as _;

/// Generated `api` package (`proto/api.proto`): client-facing `DataStreamDB` API.
pub mod api {
    #![allow(missing_docs, clippy::all, clippy::pedantic)]
    include!(concat!(env!("OUT_DIR"), "/api.rs"));

    pub use self::facet::ValType as FacetValType;
}

/// Generated `pb` package (`proto/pb.proto`): worker/raft/zero internals.
pub mod pb {
    #![allow(missing_docs, clippy::all, clippy::pedantic)]
    include!(concat!(env!("OUT_DIR"), "/pb.rs"));
}

/// Generated `badgerpb4` package (`proto/badger.proto`): partial mirrors.
pub mod badgerpb4 {
    #![allow(missing_docs, clippy::all, clippy::pedantic)]
    include!(concat!(env!("OUT_DIR"), "/badgerpb4.rs"));
}

/// etcd raft wire mirrors for the write-ahead log (hand-authored).
pub mod raftpb;

// Root re-exports keep the pre-codegen paths (`M0`-`M4` dependents) working.
// New code should prefer the `pb::` / `api::` paths.
pub use pb::{
    BackupPostingList, DirectedEdge, FacetParam, FacetParams, Facets, FacetsList, FilterTree,
    LangList, List, Metadata, OptionPair, OracleDelta, Order, Posting, PostingList, SchemaRequest,
    SchemaUpdate, SortMessage, SortResult, SrcFunction, TaskValue, TxnStatus, TypeUpdate, UidBlock,
    UidPack, ValueList, VectorIndexSpec,
};
pub use pb::{Function as FilterFunction, Query as TaskQuery, Result as TaskResult};
pub use pb::{directed_edge::Op as EdgeOp, metadata::HintType, posting::PostingType};
pub use pb::{posting::ValType, schema_update::Directive};

impl SchemaUpdate {
    /// Typed view of [`SchemaUpdate::value_type`] (unknown discriminants err).
    #[must_use]
    pub fn value_type_enum(&self) -> Option<ValType> {
        ValType::try_from(self.value_type).ok()
    }

    /// Typed view of [`SchemaUpdate::directive`] (unknown discriminants err).
    #[must_use]
    pub fn directive_enum(&self) -> Option<Directive> {
        Directive::try_from(self.directive).ok()
    }
}

impl Metadata {
    /// Records a hint for a predicate.
    pub fn set_hint(&mut self, pred: &str, hint: HintType) {
        self.pred_hints.insert(pred.to_owned(), hint as i32);
    }

    /// Reads the hint for a predicate, if any is valid.
    #[must_use]
    pub fn hint(&self, pred: &str) -> Option<HintType> {
        self.pred_hints
            .get(pred)
            .and_then(|v| HintType::try_from(*v).ok())
    }
}

/// Internal transaction context (posting layer bookkeeping).
///
/// This is intentionally not `api::TxnContext`: neither `pb.proto` nor
/// `api.proto` defines this three-field shape, and it never crosses the wire.
#[derive(Clone, PartialEq, prost::Message)]
pub struct TxnContext {
    /// Start timestamp.
    #[prost(uint64, tag = "1")]
    pub start_ts: u64,
    /// Commit timestamp (0 while open).
    #[prost(uint64, tag = "2")]
    pub commit_ts: u64,
    /// Whether the transaction aborted.
    #[prost(bool, tag = "3")]
    pub aborted: bool,
}

/// Decode error wrapper for prost payloads.
#[derive(Clone, Debug, thiserror::Error, PartialEq, Eq)]
#[error("protobuf decode failed: {0}")]
pub struct DecodeError(String);

impl From<prost::DecodeError> for DecodeError {
    fn from(err: prost::DecodeError) -> Self {
        Self(err.to_string())
    }
}

/// Decodes a [`DirectedEdge`] from wire bytes.
///
/// # Errors
///
/// Returns [`DecodeError`] when the bytes are not a valid encoding.
pub fn decode_edge(bytes: &[u8]) -> Result<DirectedEdge, DecodeError> {
    DirectedEdge::decode(bytes).map_err(DecodeError::from)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn edge_roundtrips_on_the_wire() {
        let edge = DirectedEdge {
            entity: 42,
            attr: "name".to_owned(),
            value: b"Ada".to_vec(),
            value_type: ValType::String as i32,
            value_id: 7,
            lang: "en".to_owned(),
            op: EdgeOp::Set as i32,
            facets: vec![api::Facet {
                key: "since".to_owned(),
                value: vec![1],
                val_type: api::FacetValType::Bool as i32,
                tokens: Vec::new(),
                alias: String::new(),
            }],
            allowed_preds: vec!["name".to_owned()],
            namespace: 2,
        };
        let bytes = edge.encode_to_vec();
        assert_eq!(decode_edge(&bytes).as_ref(), Ok(&edge));
    }

    #[test]
    fn posting_roundtrips_on_the_wire() {
        let posting = Posting {
            uid: 9,
            value: b"x".to_vec(),
            val_type: ValType::String as i32,
            posting_type: PostingType::Value as i32,
            lang_tag: b"en".to_vec(),
            facets: Vec::new(),
            op: 0,
            start_ts: 10,
            commit_ts: 11,
        };
        let bytes = posting.encode_to_vec();
        assert_eq!(Posting::decode(bytes.as_slice()).as_ref(), Ok(&posting));
    }

    #[test]
    fn posting_type_and_edge_op_discriminants_match_pb_proto() {
        assert_eq!(PostingType::Ref as i32, 0);
        assert_eq!(PostingType::Value as i32, 1);
        assert_eq!(PostingType::ValueLang as i32, 2);
        assert_eq!(EdgeOp::Set as i32, 0);
        assert_eq!(EdgeOp::Del as i32, 1);
        assert_eq!(EdgeOp::Ovr as i32, 2);
        assert_eq!(api::FacetValType::String as i32, 0);
        assert_eq!(api::FacetValType::Int as i32, 1);
        assert_eq!(api::FacetValType::Float as i32, 2);
        assert_eq!(api::FacetValType::Bool as i32, 3);
        assert_eq!(api::FacetValType::Datetime as i32, 4);
    }

    #[test]
    fn garbage_fails_decode() {
        assert!(decode_edge(&[0xff, 0xff, 0xff, 0xff, 0xff]).is_err());
    }

    #[test]
    fn val_type_discriminants_match_pb_proto() {
        assert_eq!(ValType::Default as i32, 0);
        assert_eq!(ValType::Binary as i32, 1);
        assert_eq!(ValType::Int as i32, 2);
        assert_eq!(ValType::Float as i32, 3);
        assert_eq!(ValType::Bool as i32, 4);
        assert_eq!(ValType::Datetime as i32, 5);
        assert_eq!(ValType::Geo as i32, 6);
        assert_eq!(ValType::Uid as i32, 7);
        assert_eq!(ValType::Password as i32, 8);
        assert_eq!(ValType::String as i32, 9);
        assert_eq!(ValType::Object as i32, 10);
        assert_eq!(ValType::Bigfloat as i32, 11);
        assert_eq!(ValType::Vfloat as i32, 12);
    }

    #[test]
    fn schema_update_roundtrips() {
        let update = SchemaUpdate {
            predicate: "0-name".to_owned(),
            value_type: ValType::String as i32,
            directive: Directive::Index as i32,
            tokenizer: vec!["exact".to_owned()],
            count: true,
            list: true,
            index_specs: vec![VectorIndexSpec {
                name: "hnsw".to_owned(),
                options: vec![OptionPair {
                    key: "metric".to_owned(),
                    value: "euclidean".to_owned(),
                }],
            }],
            ..Default::default()
        };
        let bytes = update.encode_to_vec();
        let back = SchemaUpdate::decode(bytes.as_slice()).expect("decode");
        assert_eq!(back, update);
        assert_eq!(back.value_type_enum(), Some(ValType::String));
        assert_eq!(back.directive_enum(), Some(Directive::Index));
    }

    #[test]
    fn metadata_hints_roundtrip() {
        let mut meta = Metadata::default();
        meta.set_hint("friend", HintType::List);
        meta.set_hint("name", HintType::Single);
        let bytes = meta.encode_to_vec();
        let back = Metadata::decode(bytes.as_slice()).expect("decode");
        assert_eq!(back.hint("friend"), Some(HintType::List));
        assert_eq!(back.hint("name"), Some(HintType::Single));
        assert_eq!(back.hint("missing"), None);
    }

    #[test]
    fn directive_and_hint_discriminants_match_pb_proto() {
        assert_eq!(Directive::None as i32, 0);
        assert_eq!(Directive::Index as i32, 1);
        assert_eq!(Directive::Reverse as i32, 2);
        assert_eq!(Directive::Delete as i32, 3);
        assert_eq!(HintType::Default as i32, 0);
        assert_eq!(HintType::Single as i32, 1);
        assert_eq!(HintType::List as i32, 2);
    }

    #[test]
    fn list_uses_packed_fixed64_wire_encoding() {
        // Proto3 packs repeated fixed64: tag 0x0A, length, then 8 bytes LE per uid.
        let list = List {
            uids: vec![1, 0x0102_0304_0506_0708],
        };
        let bytes = list.encode_to_vec();
        assert_eq!(
            bytes,
            [
                0x0A, 0x10, //
                0x01, 0, 0, 0, 0, 0, 0, 0, //
                0x08, 0x07, 0x06, 0x05, 0x04, 0x03, 0x02, 0x01,
            ]
        );
        assert_eq!(List::decode(bytes.as_slice()).as_ref(), Ok(&list));
    }

    #[test]
    fn api_txn_context_wire_matches_dgo() {
        // Hand-computed per the protobuf spec; pins dgo interop field numbers.
        let txn = api::TxnContext {
            start_ts: 1,
            commit_ts: 2,
            aborted: true,
            keys: vec!["a".to_owned()],
            preds: vec!["p".to_owned()],
            hash: "h".to_owned(),
        };
        assert_eq!(
            txn.encode_to_vec(),
            [
                0x08, 0x01, // start_ts = 1
                0x10, 0x02, // commit_ts = 2
                0x18, 0x01, // aborted = true
                0x22, 0x01, b'a', // keys = ["a"]
                0x2A, 0x01, b'p', // preds = ["p"]
                0x32, 0x01, b'h', // hash = "h"
            ]
        );
        let back = api::TxnContext::decode(txn.encode_to_vec().as_slice()).expect("decode");
        assert_eq!(back, txn);
    }

    #[test]
    fn api_request_with_vars_and_mutation_roundtrips() {
        let req = api::Request {
            start_ts: 9,
            query: "{ q(func: has(name)) { uid } }".to_owned(),
            vars: [("$a".to_owned(), "1".to_owned())].into_iter().collect(),
            read_only: true,
            best_effort: false,
            mutations: vec![api::Mutation {
                set_nquads: b"_:a <name> \"Ada\" .".to_vec(),
                commit_now: true,
                ..Default::default()
            }],
            commit_now: true,
            resp_format: api::request::RespFormat::Rdf as i32,
            hash: String::new(),
        };
        let bytes = req.encode_to_vec();
        let back = api::Request::decode(bytes.as_slice()).expect("decode");
        assert_eq!(back, req);
    }

    #[test]
    fn cluster_messages_roundtrip() {
        let member = pb::Member {
            id: 7,
            group_id: 1,
            addr: "localhost:7080".to_owned(),
            leader: true,
            ..Default::default()
        };
        let group = pb::Group {
            members: [(7_u64, member.clone())].into_iter().collect(),
            tablets: [(
                "name".to_owned(),
                pb::Tablet {
                    group_id: 1,
                    predicate: "name".to_owned(),
                    ..Default::default()
                },
            )]
            .into_iter()
            .collect(),
            ..Default::default()
        };
        let state = pb::MembershipState {
            counter: 3,
            groups: [(1_u32, group)].into_iter().collect(),
            max_uid: 100,
            ..Default::default()
        };
        let bytes = state.encode_to_vec();
        let back = pb::MembershipState::decode(bytes.as_slice()).expect("decode");
        assert_eq!(back, state);
        assert!(back.groups[&1].members[&7].leader);

        let proposal = pb::ZeroProposal {
            member: Some(member),
            max_uid: 101,
            ..Default::default()
        };
        let bytes = proposal.encode_to_vec();
        assert_eq!(
            pb::ZeroProposal::decode(bytes.as_slice()).as_ref(),
            Ok(&proposal)
        );
    }

    #[test]
    fn grpc_services_are_generated() {
        // Compile-time proof that tonic clients/servers exist for all four
        // services (DataStreamDB, Raft, Zero, Worker).
        let _ = api::data_stream_db_client::DataStreamDbClient::<tonic::transport::Channel>::new;
        let _ = pb::raft_client::RaftClient::<tonic::transport::Channel>::new;
        let _ = pb::zero_client::ZeroClient::<tonic::transport::Channel>::new;
        let _ = pb::worker_client::WorkerClient::<tonic::transport::Channel>::new;
    }
}
